  SELECT 'cross-business:TableSessionItem.billedOrderId->Order'::text AS "check", count(*) AS violations FROM "TableSessionItem" t JOIN "Order" p ON p.id = t."billedOrderId" WHERE (SELECT o3."businessId" FROM "Outlet" o3 WHERE o3.id = p."outletId") IS NOT NULL AND (SELECT (SELECT o2."businessId" FROM "Outlet" o2 WHERE o2.id = o1."outletId") FROM "TableSession" o1 WHERE o1.id = t."sessionId") IS NOT NULL AND (SELECT o3."businessId" FROM "Outlet" o3 WHERE o3.id = p."outletId") <> (SELECT (SELECT o2."businessId" FROM "Outlet" o2 WHERE o2.id = o1."outletId") FROM "TableSession" o1 WHERE o1.id = t."sessionId")
