  SELECT 'cross-business:WalletTxn.outletId->Outlet'::text AS "check", count(*) AS violations FROM "WalletTxn" t JOIN "Outlet" p ON p.id = t."outletId" WHERE p."businessId" IS NOT NULL AND (SELECT o1."businessId" FROM "Customer" o1 WHERE o1.id = t."customerId") IS NOT NULL AND p."businessId" <> (SELECT o1."businessId" FROM "Customer" o1 WHERE o1.id = t."customerId")
