  SELECT 'orphan:Setting.scope'::text AS "check", count(*) AS violations FROM "Setting" t WHERE t.scope <> 'GLOBAL' AND NOT EXISTS (SELECT 1 FROM "Outlet" o WHERE o.id = t.scope) AND NOT EXISTS (SELECT 1 FROM "Business" b WHERE b.id = t.scope)
