  SELECT 'cross-business:ChannelRequest.items[].menuItemId'::text AS "check", count(*) AS violations FROM "ChannelRequest" t CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(t.items) = 'array' THEN t.items ELSE '[]' END) x(e) WHERE x.e ? 'menuItemId' AND NOT EXISTS (SELECT 1 FROM "MenuItem" m JOIN "Outlet" o ON o."businessId" = m."businessId" WHERE m.id = x.e->>'menuItemId' AND o.id = t."outletId")
